    add(name,label,(x,y),level,[(x-rx,y-ry*.4),(x-rx*.65,y+ry*.65),(x-rx*.1,y+ry),(x+rx*.65,y+ry*.7),(x+rx,y+ry*.12),(x+rx*.6,y-ry*.8),(x-rx*.2,y-ry)])
